const content = $json.choices[0].message.content || "";

// Split using empty line between title and hashtags
const parts = content.split(/\n\s*\n/);

const title = parts[0] ? parts[0].trim() : "";
const hashtags = parts[1] ? parts[1].trim() : "";

return [
  {
    json: {
      Title: title,
      hashtags: hashtags
    }
  }
];

